-- V33__seed_turkey_earthquake_stress_scenario_paths.sql
-- Seeds 177 deterministic asset-path rows for the 2023 Türkiye earthquake scenario.

SET NOCOUNT ON;

DECLARE @Paths TABLE (
    scenario_code VARCHAR(50) NOT NULL,
    asset_code NVARCHAR(50) NOT NULL,
    path_date DATE NOT NULL,
    day_index SMALLINT NOT NULL,
    close_value DECIMAL(20, 8) NOT NULL,
    impact DECIMAL(20, 12) NOT NULL,
    PRIMARY KEY (scenario_code, asset_code, day_index)
);


IF (SELECT COUNT(*) FROM @Paths WHERE scenario_code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023') <> 177
BEGIN
    THROW 50031, 'Unexpected path row count for S04_TURKEY_EARTHQUAKE_SHOCK_2023.', 1;
END;

IF (SELECT COUNT(DISTINCT asset_code) FROM @Paths WHERE scenario_code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023') <> 59
BEGIN
    THROW 50032, 'Unexpected asset coverage for S04_TURKEY_EARTHQUAKE_SHOCK_2023.', 1;
END;

IF (SELECT MIN(day_index) FROM @Paths WHERE scenario_code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023') <> 0
   OR (SELECT MAX(day_index) FROM @Paths WHERE scenario_code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023') <> 4
BEGIN
    THROW 50033, 'Unexpected path day range for S04_TURKEY_EARTHQUAKE_SHOCK_2023.', 1;
END;

IF EXISTS (
    SELECT 1
    FROM @Paths p
    LEFT JOIN dbo.stress_scenarios s ON s.code = p.scenario_code
    WHERE s.id IS NULL
)
BEGIN
    THROW 50034, 'Stress path dataset contains an unknown scenario.', 1;
END;

IF EXISTS (
    SELECT 1
    FROM @Paths p
    LEFT JOIN dbo.assets a ON a.asset_code = p.asset_code
    WHERE a.id IS NULL
)
BEGIN
    THROW 50035, 'Stress path dataset contains an unknown asset.', 1;
END;

UPDATE target
SET
    target.path_date = source.path_date,
    target.close_value = source.close_value,
    target.impact = source.impact
FROM dbo.stress_scenario_asset_paths target
JOIN dbo.stress_scenarios scenario ON scenario.id = target.scenario_id
JOIN dbo.assets asset ON asset.id = target.asset_id
JOIN @Paths source
    ON source.scenario_code = scenario.code
   AND source.asset_code = asset.asset_code
   AND source.day_index = target.day_index;

    scenario_id, asset_id, path_date, day_index, close_value, impact
)
SELECT scenario.id, asset.id, source.path_date, source.day_index, source.close_value, source.impact
FROM @Paths source
JOIN dbo.stress_scenarios scenario ON scenario.code = source.scenario_code
JOIN dbo.assets asset ON asset.asset_code = source.asset_code
WHERE NOT EXISTS (
    SELECT 1
    FROM dbo.stress_scenario_asset_paths existing
    WHERE existing.scenario_id = scenario.id
      AND existing.asset_id = asset.id
      AND existing.day_index = source.day_index
);

IF (
    SELECT COUNT(*)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023'
) <> 177
BEGIN
    THROW 50036, 'Persisted path row count is invalid for S04_TURKEY_EARTHQUAKE_SHOCK_2023.', 1;
END;

IF (
    SELECT COUNT(DISTINCT path.asset_id)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S04_TURKEY_EARTHQUAKE_SHOCK_2023'
) <> 59
BEGIN
    THROW 50037, 'Persisted path asset coverage is invalid for S04_TURKEY_EARTHQUAKE_SHOCK_2023.', 1;
END;

SET NOCOUNT OFF;
